import fs from "node:fs/promises";
import path from "node:path";
import { gunzipSync } from "node:zlib";
import { createHash, randomUUID } from "node:crypto";

// This installer contains the reviewed update files; it needs no sibling folders.
const embeddedPackage = JSON.parse(gunzipSync(Buffer.from("", "base64")).toString("utf8"));
const sha256 = bytes => createHash("sha256").update(bytes).digest("hex");
const exists = async file => { try { return await fs.lstat(file); } catch (e) { if (e.code === "ENOENT") return null; throw e; } };
function allowed(relative) {
  return typeof relative === "string" && !relative.includes("\\") && !relative.split("/").some(part => !part || part === "." || part === "..") &&
    !relative.startsWith("/") && !relative.startsWith("backend/data/") && !relative.startsWith("backend/storage/") &&
    (relative === "package.json" || relative === "package-lock.json" || /^(README\.md|INSTRUCCIONES\.txt|INTEGRACION_API\.md|VALIDACION_COMPRAS\.md|FACTURAMA_SANDBOX\.md)$/.test(relative) ||
      /^(backend|shared|public|tests|supabase)\/.+\.(mjs|js|html|css|sql)$/.test(relative));
}
async function safeTarget(root, relative) {
  let current = root;
  for (const part of relative.split("/")) {
    current = path.join(current, part);
    const info = await exists(current);
    if (info?.isSymbolicLink()) throw new Error(`No se reemplaza un enlace simbolico: ${relative}`);
  }
  return current;
}

try {
  const destination = await fs.realpath(path.resolve(process.argv[2] || process.cwd()));
  const pkg = JSON.parse(await fs.readFile(path.join(destination, "package.json"), "utf8"));
  if (pkg.name !== "facturacion-dinamica-v1" || !(await exists(path.join(destination, "backend/server.mjs")))) throw new Error("La carpeta indicada no corresponde al proyecto de facturacion.");
  const versionParts = value => String(value).split(".").map(Number);
  const compareVersions = (a,b) => { const aa=versionParts(a),bb=versionParts(b); for(let i=0;i<3;i++){const difference=(aa[i]||0)-(bb[i]||0);if(difference)return difference;}return 0; };
  if (!/^\d+\.\d+\.\d+$/.test(pkg.version||"") || compareVersions(pkg.version,embeddedPackage.minimum_base_version)<0) throw new Error("Esta actualización requiere la base 1.15.2 o posterior. Conserva tu proyecto y revisa su package.json.");
  if (compareVersions(pkg.version,embeddedPackage.version)>0) throw new Error("Tu proyecto tiene una versión posterior. No se instalará una actualización anterior.");
  const manifest = embeddedPackage;
  if (!Array.isArray(manifest.files) || manifest.files.length === 0) throw new Error("El paquete no tiene archivos para instalar.");
  const seen = new Set(), files = [];
  for (const item of manifest.files) {
    if (!allowed(item.path) || seen.has(item.path)) throw new Error("El paquete contiene una ruta no permitida.");
    seen.add(item.path);
    const bytes = Buffer.from(item.contentBase64, "base64");
    if (sha256(bytes) !== item.sha256) throw new Error(`El paquete esta incompleto: ${item.path}. Descarga nuevamente el instalador.`);
    const target = await safeTarget(destination, item.path), info = await exists(target);
    if (info && !info.isFile()) throw new Error(`La ruta existente no es un archivo: ${item.path}`);
    files.push({ relative: item.path, target, bytes, existed: Boolean(info) });
  }
  const backup = await safeTarget(destination, path.join("respaldos-actualizacion", `v1.17.5-${new Date().toISOString().replace(/[:.]/g, "-")}-${randomUUID().slice(0, 8)}`));
  await fs.mkdir(backup, { recursive: true });
  for (const file of files.filter(f => f.existed)) {
    const copy = path.join(backup, file.relative); await fs.mkdir(path.dirname(copy), { recursive: true }); await fs.copyFile(file.target, copy);
  }
  await fs.writeFile(path.join(backup, "archivos-agregados.json"), JSON.stringify(files.filter(f => !f.existed).map(f => f.relative), null, 2));
  const installed = [];
  try {
    for (const file of files) {
      await fs.mkdir(path.dirname(file.target), { recursive: true });
      const temporary = `${file.target}.${randomUUID()}.tmp`;
      try { await fs.writeFile(temporary, file.bytes, { flag: "wx" }); await fs.rename(temporary, file.target); }
      finally { await fs.rm(temporary, { force: true }); }
      installed.push(file);
    }
  } catch (error) {
    for (const file of installed.reverse()) {
      if (file.existed) await fs.copyFile(path.join(backup, file.relative), file.target);
      else await fs.rm(file.target, { force: true });
    }
    throw error;
  }
  console.log(`Actualizacion acumulada v1.17.5 instalada: ${files.length} archivos.`);
  console.log(`Respaldo de los archivos anteriores: ${backup}`);
  console.log("Tu .env, credenciales, datos, documentos y node_modules se conservan.");
  console.log("No se ejecuto SQL. Conserva tu .env y ejecuta npm start desde tu proyecto.");
} catch (error) { console.error(`No se pudo instalar: ${error.message}`); process.exitCode = 1; }
